function ownAndInherited(obj) {
  const own = Object.keys(obj);
  const inherited = [];
  for (const key in obj) {
    if (!Object.hasOwn(obj, key)) inherited.push(key);
  }
  return { own: own.sort(), inherited: inherited.sort() };
}

function bindMethods(obj) {
  for (const key of Object.keys(obj)) {
    if (typeof obj[key] === "function") obj[key] = obj[key].bind(obj);
  }
  return obj;
}

function later(obj, methodName) {
  return (...args) => obj[methodName](...args);
}

unitTests:
test("own versus inherited", () => {
  const base = { kind: "animal", legs: 4 };
  const cat = Object.create(base);
  cat.name = "Tom";
  cat.legs = 3;
  checkEq(ownAndInherited(cat), { own: ["legs", "name"], inherited: ["kind"] });
  checkEq(ownAndInherited({ b: 1, a: 2 }), { own: ["a", "b"], inherited: [] });
});

test("bound methods keep this", () => {
  const counter = { n: 0, inc() { this.n++; return this.n; }, label: "c" };
  check(bindMethods(counter) === counter, "should return the same object");
  const inc = counter.inc;
  checkEq(inc(), 1);
  checkEq([1, 2].map(counter.inc), [2, 3]);
  checkEq(counter.label, "c");
});

test("late lookup keeps this", () => {
  const user = { name: "Ada", greet(greeting) { return `${greeting}, ${this.name}`; } };
  const f = later(user, "greet");
  checkEq(f("Hi"), "Hi, Ada");
  user.greet = function (g) { return `${g}!! ${this.name}`; };
  checkEq(f("Yo"), "Yo!! Ada");
  user.name = "Grace";
  checkEq(f("Hi"), "Hi!! Grace");
});

